import math
def control(obs):
    cam=obs.get('views',{}).get('camera')
    h=obs['hitch_deg']
    if not cam:
        return (h*2,0,-23)
    sides=[[],[]]
    th=math.radians(obs['rig']['trailer_heading_deg'])
    for b,d in cam.get('walls',[]):
        a=math.radians(b)-th
        u=-d*math.cos(a); y=d*math.sin(a)
        if u>0.4 and abs(y)>0.5:
            sides[0 if y>0 else 1].append((u,y))
    vals=[]
    for pts in sides:
        if len(pts)<2: continue
        pts=sorted(pts,key=lambda p:abs(p[0]-3.2))[:5]
        n=len(pts); sx=sum(p[0] for p in pts); sy=sum(p[1] for p in pts)
        den=sum(p[0]*p[0] for p in pts)-sx*sx/n
        slope=(sum(x*y for x,y in pts)-sx*sy/n)/max(den,0.05)
        vals.append(sy/n+slope*(3.2-sx/n))
    if len(vals)!=2:
        wake('Need a clearer view of the course')
        return (0,0,-23)
    y=sum(vals)/2
    desired=math.degrees(math.atan(5.2*y/(3.2**2+y*y)))
    desired=max(-29,min(29,desired))
    eq=math.degrees(math.atan(2.75*math.sin(math.radians(h))/(2.6+1.05*math.cos(math.radians(h)))))
    steer=max(-34,min(34,eq+2.2*(h-desired)))
    return (steer,-0.8,-23)

